import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Claude Fable 5 & Claude Mythos 5 System Card","description":"","frontmatter":{"url":"https://www.anthropic.com/claude-fable-5-mythos-5-system-card","title":"Claude Fable 5 & Claude Mythos 5 System Card","archived_date":"2026-06-24T00:00:00.000Z","authors":["Anthropic"],"domains":["system-card"],"published_date":"2026-06-09T00:00:00.000Z","source_url":"https://www.anthropic.com/claude-fable-5-mythos-5-system-card","web_only":true},"headers":[],"relativePath":"research/papers/2026-06-09-claude-fable-5-mythos-5-system-card.md","filePath":"research/papers/2026-06-09-claude-fable-5-mythos-5-system-card.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-06-09-claude-fable-5-mythos-5-system-card.md"};function l(n,e,d,i,c,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="claude-fable-5-claude-mythos-5-system-card" tabindex="-1">Claude Fable 5 &amp; Claude Mythos 5 System Card <a class="header-anchor" href="#claude-fable-5-claude-mythos-5-system-card" aria-label="Permalink to &quot;Claude Fable 5 &amp; Claude Mythos 5 System Card&quot;">​</a></h1><p><strong>Source</strong>: Anthropic 官方 system card（web-only，無 arXiv PDF）— <a href="https://www.anthropic.com/claude-fable-5-mythos-5-system-card" target="_blank" rel="noreferrer">https://www.anthropic.com/claude-fable-5-mythos-5-system-card</a> （原始 URL 307 重導向至官方 PDF <code>www-cdn.anthropic.com/.../Claude%20Fable%205%20&amp;%20Claude%20Mythos%205%20System%20Card.pdf</code>，內容相同。） <strong>Published</strong>: June 9, 2026</p><blockquote><p>依官方公開資訊整理；數字以可交叉驗證者為主，不確定處保守描述。官方 system card 約 319 頁。</p></blockquote><hr><h2 id="摘要-依官網內容整理" tabindex="-1">摘要（依官網內容整理） <a class="header-anchor" href="#摘要-依官網內容整理" aria-label="Permalink to &quot;摘要（依官網內容整理）&quot;">​</a></h2><p>Fable 5 與 Mythos 5 為同一底層模型的雙版本：<strong>Fable 5</strong> 是「Mythos-class」但做成可一般使用的最強 GA 模型；<strong>Mythos 5</strong> 為同模型解除部分安全限制版，僅透過 Project Glasswing 提供給經審核的 cyberdefender，不對公眾開放。Fable 5 主打多日自主任務、persistent memory、強視覺（從原始截圖通關 Pokémon FireRed）。</p><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="模型與定位" tabindex="-1">模型與定位 <a class="header-anchor" href="#模型與定位" aria-label="Permalink to &quot;模型與定位&quot;">​</a></h3><ul><li><strong>Claude Fable 5</strong>：最強 GA 模型，Mythos-class 安全化版本。</li><li><strong>Claude Mythos 5</strong>：同底層、解除部分 safeguard，限 Project Glasswing 防禦夥伴。</li></ul><h3 id="關鍵能力-安全評估數字-依官方公開資訊整理" tabindex="-1">關鍵能力 / 安全評估數字（依官方公開資訊整理） <a class="header-anchor" href="#關鍵能力-安全評估數字-依官方公開資訊整理" aria-label="Permalink to &quot;關鍵能力 / 安全評估數字（依官方公開資訊整理）&quot;">​</a></h3><ul><li><strong>SWE-bench Verified</strong>：<strong>95.5%</strong>。</li><li><strong>SWE-bench Pro</strong>：<strong>80.3%</strong>（任何受測模型最高，領先 Opus 4.8 的 69.2%）。</li><li><strong>能力亮點</strong>：多日自主任務、persistent memory、視覺從截圖通關 Pokémon FireRed。</li><li><strong>AI Safety Level</strong>：<strong>ASL-3</strong>；化生分級 <strong>CB-1</strong>（具非新穎化生武器資訊能力，但未跨 CB-2 新穎武器門檻）。</li><li><strong>安全分類器</strong>：對 cyber/bio/chem/model-distillation 請求跑保守分類器；約 <strong>1/20</strong> prompt 會被保守過濾「靜默降級」至舊版 Opus 4.8。</li></ul><h3 id="值得注意章節" tabindex="-1">值得注意章節 <a class="header-anchor" href="#值得注意章節" aria-label="Permalink to &quot;值得注意章節&quot;">​</a></h3><ul><li><strong>雙版本治理模型</strong>：同一強模型，GA 版（Fable）與受限版（Mythos）並行——能力與安全解耦的部署範式。</li><li><strong>靜默降級機制</strong>：保守 filter 將約 5% prompt 降級到 Opus 4.8——是「安全優先於一致體驗」的明確 trade-off。</li></ul><hr><h2 id="workspace-關聯-評估" tabindex="-1">Workspace 關聯（評估） <a class="header-anchor" href="#workspace-關聯-評估" aria-label="Permalink to &quot;Workspace 關聯（評估）&quot;">​</a></h2><ul><li><strong><code>pilot</code>（tier=frontier，原 <code>fable-pilot</code>） 直接對應</strong>：本卡是 <code>pilot</code>（tier=frontier，原 <code>fable-pilot</code>）（Mythos-class 全能模式）的官方底座——95.5% SWE-bench / 80.3% SWE-bench Pro 是其「最強稽核/優化/架構」定位的能力證據。</li><li><strong>靜默降級 ↔ cyber/bio 路由紀律</strong>：CLAUDE.md「Fable 對 cyber/bio silent fallback → Opus，該域直接指定 Opus」——本卡的 1/20 降級至 Opus 4.8 正是此機制；故 cyber/bio 任務應顯式指定 Opus 避免賭路由。</li><li><strong>persistent memory ↔ memory-compactor / 長期記憶回路</strong>：多日自主 + persistent memory 呼應 core.md「長期記憶回路（Compounding Engineering）」與 MEMORY.md 設計。</li><li><strong>CB-1 / ASL-3 ↔ 安全例外鐵律</strong>：core.md「加密原語/輸入驗證永遠獨立函式」等安全紅線不因模型更強而放寬。</li></ul>',17)])])}const p=a(s,[["render",l]]);export{u as __pageData,p as default};
